void tsk_rs_init( void )
{
    Tsk tsk ;
	
    #pragma push
    #pragma diag_suppress 188    
    tsk_rs_takeover_cfg     = TSK_RS_TAKEOVER_AFTERMARKET | TSK_RS_TAKEOVER_OEM ; 
    #pragma pop
    
    tsk_rs_takeover_timeout = TSK_RS_TAKEOVER_TIMEOUT ;
    tsk_rs_idle             = FALSE ;
    
    tsk_rs_pip = os_pip_create   ( TSK_RS_PIP_SIZE );        

    tsk_rs_reg = reg_table_create( REG_ATOMIC_USE_RES );

    tsk        = os_tsk_create   ( (TskFunc)tsk_rs_tsk , TSK_RS_PRI , TSK_RS_STK , 0 , "tsk_rs_tsk" );    
    
    tsk_rs_gwr = FALSE ; 
    tsk_rs_ign = FALSE ; 
    tsk_rs_str = FALSE ;
            
    tsk_rs_cmd_init   ();    
    tsk_rs_tke_init   ();            

    os_tsk_start(tsk,NULL);
	
	TRACE( "\r\nTSK_RS INIT\r\n" );
}


//--------------------------------------------------------------------------//

void tsk_rs_update_cfg( Tsk_Rs_Takeover takeover_cfg )
{
    ATOMIC(tsk_rs_takeover_cfg = takeover_cfg);
}

//--------------------------------------------------------------------------//

void tsk_rs_oem_disarm(Boolean enabled)
{
    ATOMIC(tsk_rs_do_oem_disarm = enabled);
}

